/**
 * GATE L4a-D / L4a-J — THE AI DISPATCH TABLE IS CONTRACT (lane L4a).
 *
 * `OG_AI_*` is generated by `scripts/payload/transcribeAi.py` from `NPCManager.as`
 * and `XMLNpc.as` — never hand-keyed (GAUNTLET.md §2, "a script beats a swarm").
 * Same two-part shape as `tests/ogNpcData.test.ts`:
 *
 *   1. STRUCTURAL PINS that run everywhere, with no decompiled payload present.
 *   2. A BYTE-CHECK that re-parses the AS3 with its own INDEPENDENT grammar — a
 *      flat line regex here, versus the generator's function-scoped state machine —
 *      and demands the committed table match branch for branch.
 *
 * ⛔ THIS IS THE MAP, NOT THE BEHAVIOUR. Building the 34 enemy actors is L4b
 * (GAUNTLET.md §2 routes it to Fable 5 @ `high`), and nothing here is wired into the
 * duel — that moves `src/core/Sim.ts` and `tests/duel-baseline.test.ts`, §4's
 * no-touch list, and belongs to L5 alone.
 *
 * What this file exists to stop, all four measured 2026-09-07:
 *   - Recording only `createNPC` and calling the map complete. There are THREE
 *     dispatches over the same value space and they disagree by design.
 *   - Recording only the class name. `EnemyPlayer` is at ai 0, 9 AND 14 and
 *     `EnemySpearElite` at 28 and 37 — the constructor flags ARE the behaviour.
 *   - Smoothing `createNPC`'s `default:`, which traces and leaves `actor` null for
 *     the very next statement to dereference. The room dispatches do not.
 *   - "Verifying" the 34 distinct `<ai>` values with the 34 `Enemy*.as` classes on
 *     disk. Same number, disjoint sets — pinned apart below.
 *
 * ⚠️ C2 — the decompiled scripts are the ANDROID build (v0.682); no web-side
 * artifact corroborates them yet (GAUNTLET.md §2.1).
 */
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import {
  OG_AI_ABSENT_DEFAULT,
  OG_AI_ANIMAL_VALUES,
  OG_AI_CODE_OVERRIDES,
  OG_AI_CREATE_NPC,
  OG_AI_CREATE_ROOM_NPC,
  OG_AI_CREATE_ROOM_NPC_PROCGEN,
  OG_AI_DUEL_PLACEMENT,
  type OgAiDispatch,
} from '../src/config/ogAi';
import { OG_NPCS } from '../src/config/ogNpcs';

const ALL: readonly OgAiDispatch[] = [
  OG_AI_CREATE_NPC,
  OG_AI_CREATE_ROOM_NPC,
  OG_AI_CREATE_ROOM_NPC_PROCGEN,
];

describe('L4a-D structural pins — run everywhere, no decompiled payload needed', () => {
  it('carries all THREE dispatches, at the widths the source has', () => {
    expect(ALL.map((d) => [d.fn, d.line, d.cases.length])).toEqual([
      ['createNPC', 500, 38],
      ['createRoomNPC', 671, 13],
      ['createRoomNPCProcGen', 749, 2],
    ]);
  });

  it('createNPC covers 0..37 DENSELY — a gap would be a case the parser skipped', () => {
    expect(OG_AI_CREATE_NPC.cases.map((c) => c.ai)).toEqual([...Array(38).keys()]);
  });

  it('THE ARGUMENTS ARE THE BEHAVIOUR — 5 rows would collapse into 2 without them', () => {
    const byAi = new Map(OG_AI_CREATE_NPC.cases.map((c) => [c.ai, c]));
    // EnemyPlayer at three ai values, three different flag pairs.
    expect(byAi.get(0)?.args).toEqual(['MCSPool.getMCS()', 'true', 'false']);
    expect(byAi.get(9)?.args).toEqual(['MCSPool.getMCS()', 'false', 'false']);
    expect(byAi.get(14)?.args).toEqual(['MCSPool.getMCS()', 'false', 'true']);
    expect([0, 9, 14].map((a) => byAi.get(a)?.actor)).toEqual([
      'EnemyPlayer', 'EnemyPlayer', 'EnemyPlayer',
    ]);
    // EnemySpearElite at two, distinguished by ONE boolean.
    expect(byAi.get(28)?.args).toEqual(['MCSPool.getMCS()', 'false']);
    expect(byAi.get(37)?.args).toEqual(['MCSPool.getMCS()', 'true']);
    // 38 cases but only 35 distinct classes, precisely because of those collisions.
    expect(new Set(OG_AI_CREATE_NPC.cases.map((c) => c.actor)).size).toBe(35);
  });

  it('THE ROOM DISPATCH DISAGREES WITH THE SWITCH — same ai, different actor', () => {
    const room = new Map(OG_AI_CREATE_ROOM_NPC.cases.map((c) => [c.ai, c.actor]));
    const npc = new Map(OG_AI_CREATE_NPC.cases.map((c) => [c.ai, c.actor]));
    expect([22, 23, 26].map((a) => [npc.get(a), room.get(a)])).toEqual([
      ['EnemyGoblin', 'RoomGoblin'],
      ['EnemyOgre', 'RoomOgre'],
      ['EnemyZombie', 'RoomZombie'],
    ]);
    // ai 11 and 16 are DIFFERENT enemies in the switch and the SAME one in a room.
    expect([npc.get(11), npc.get(16)]).toEqual(['EnemyWolfAlpha', 'EnemyNianMonster']);
    expect([room.get(11), room.get(16)]).toEqual(['EnemyWolfAlpha', 'EnemyWolfAlpha']);
    const merged = OG_AI_CREATE_ROOM_NPC.cases.filter((c) => c.ai === 11 || c.ai === 16);
    expect(new Set(merged.map((c) => c.line)).size, 'the merge is ONE source line').toBe(1);
    // Most room branches carry a chase flag the switch never passes.
    expect(OG_AI_CREATE_ROOM_NPC.cases.filter((c) => c.args.includes('doChase')).length).toBe(7);
    expect(OG_AI_CREATE_NPC.cases.filter((c) => c.args.includes('doChase')).length).toBe(0);
  });

  it('THE FALLBACKS DIFFER, and createNPC\'s is a null dereference', () => {
    expect(OG_AI_CREATE_NPC.fallback.kind).toBe('none');
    if (OG_AI_CREATE_NPC.fallback.kind === 'none') {
      expect(OG_AI_CREATE_NPC.fallback.trace).toContain('createNPC error');
    }
    for (const d of [OG_AI_CREATE_ROOM_NPC, OG_AI_CREATE_ROOM_NPC_PROCGEN]) {
      expect(d.fallback.kind, d.fn).toBe('actor');
      if (d.fallback.kind === 'actor') {
        expect(d.fallback.actor).toBe('EnemyCivilian');
        expect(d.fallback.args).toEqual(['MCSPool.getMCS()', 'doChase']);
      }
    }
  });

  it('the FOUR in-code ai overrides are recorded, and the read-or-default is NOT', () => {
    expect(OG_AI_CODE_OVERRIDES.map((o) => [o.line, o.assigns])).toEqual([
      [315, '0'],
      [479, '32'],
      [523, '33'],
      [586, 'bossxml.ai'],
    ]);
    // XMLNpc.as:137/:141 are the constructor's read-or-default; that rule lives on
    // every OG_NPCS row as `aiEffective` and must not be duplicated here.
    for (const o of OG_AI_CODE_OVERRIDES) expect([137, 141]).not.toContain(o.line);
    expect(OG_AI_ABSENT_DEFAULT).toBe(1);
  });

  it('isAnimal() partitions the ai space independently of every dispatch', () => {
    expect([...OG_AI_ANIMAL_VALUES]).toEqual([8, 10, 11, 12, 16, 17, 18, 19, 21, 24]);
    // Every animal value is dispatched by the switch, but the set is NOT any
    // dispatch's key set — it cuts across all three.
    const npc = new Set(OG_AI_CREATE_NPC.cases.map((c) => c.ai));
    const room = new Set(OG_AI_CREATE_ROOM_NPC.cases.map((c) => c.ai));
    for (const a of OG_AI_ANIMAL_VALUES) expect(npc.has(a), `ai ${String(a)}`).toBe(true);
    expect(OG_AI_ANIMAL_VALUES.filter((a) => !room.has(a))).toEqual([10, 21]);
  });

  it('every `aiEffective` in the roster resolves in createNPC', () => {
    const dispatched = new Set(OG_AI_CREATE_NPC.cases.map((c) => c.ai));
    for (const n of OG_NPCS) {
      expect(dispatched.has(n.aiEffective), `npc ${String(n.id)} ai ${String(n.aiEffective)}`).toBe(
        true,
      );
    }
    // …but the reverse does NOT hold: 4 dispatched values are never used by the data.
    const used = new Set(OG_NPCS.map((n) => n.aiEffective));
    expect([...dispatched].filter((a) => !used.has(a)).sort((a, b) => a - b)).toEqual([0, 10, 15, 16]);
  });
});

const SCRIPTS = path.join(
  fileURLToPath(new URL('..', import.meta.url)),
  'reference', 'decompiled', 'shs3_android_payload', 'scripts',
);
const HAVE_SOURCE = existsSync(path.join(SCRIPTS, 'NPCManager.as'));

describe.skipIf(!HAVE_SOURCE)('L4a-D byte-check — the table is a faithful transcription', () => {
  const mgr = readFileSync(path.join(SCRIPTS, 'NPCManager.as'), 'utf8').split('\n');
  const xmlnpc = readFileSync(path.join(SCRIPTS, 'XMLNpc.as'), 'utf8').split('\n');

  /**
   * INDEPENDENT grammar: for every committed branch, go to the line it CITES and
   * demand the constructor there is the one recorded. The generator walked forward
   * from a function declaration; this walks backward from the citation. If the
   * generator mis-attributed a branch, its line number is wrong and this fails.
   */
  const constructorAt = (line: number): { actor: string; args: string[] } | null => {
    const m = /^\s*actor = new (\w+)\((.*)\);\s*$/.exec(mgr[line - 1] ?? '');
    if (m === null) return null;
    const raw = m[2] ?? '';
    const args: string[] = [];
    let depth = 0;
    let cur = '';
    for (const ch of raw) {
      if (ch === '(') depth += 1;
      else if (ch === ')') depth -= 1;
      if (ch === ',' && depth === 0) {
        args.push(cur.trim());
        cur = '';
      } else cur += ch;
    }
    if (cur.trim() !== '') args.push(cur.trim());
    return { actor: m[1] ?? '', args };
  };

  it('every committed branch is the constructor on the line it cites', () => {
    for (const d of ALL) {
      expect(mgr[d.line - 1], `${d.fn} declaration`).toContain(`function ${d.fn}(`);
      for (const c of d.cases) {
        const at = constructorAt(c.line);
        expect(at, `${d.fn} ai ${String(c.ai)}: line ${String(c.line)} is not a constructor`)
          .not.toBeNull();
        expect(at?.actor, `${d.fn} ai ${String(c.ai)}`).toBe(c.actor);
        expect(at?.args, `${d.fn} ai ${String(c.ai)} args`).toEqual([...c.args]);
      }
      if (d.fallback.kind === 'actor') {
        expect(constructorAt(d.fallback.line)?.actor).toBe(d.fallback.actor);
      } else {
        expect(mgr[d.fallback.line - 1]).toContain('trace(');
        expect(mgr[d.fallback.line - 1]).toContain(d.fallback.trace);
      }
    }
  });

  it('the source really has 38 `case N:` labels and no branch was dropped', () => {
    // Counted flatly across the whole file, deliberately not scoped the way the
    // generator scopes it: NPCManager's ONLY switch is createNPC's.
    const cases = mgr.filter((l) => /^\s*case \d+:\s*$/.test(l));
    expect(cases.length).toBe(38);
    expect(mgr.filter((l) => l.includes('switch(xml.ai)')).length).toBe(1);
    // …and SIXTEEN flat `xml.ai == N` comparisons, not 15. Twelve + two are the room
    // dispatches' conditions (one testing two values), one is `createRoomNPCProcGen`'s
    // second, and the SIXTEENTH is `OG_AI_DUEL_PLACEMENT` at :643 — an `ai` site that
    // is not a dispatch at all. Measured 2026-09-08; the count is pinned so a new
    // `ai` comparison appearing in the source cannot slip in unrecorded.
    const conds = mgr
      .map((l, i) => ({ i: i + 1, hits: [...l.matchAll(/xml\.ai == (\d+)/g)].length }))
      .filter((r) => r.hits > 0);
    expect(conds.reduce((n, r) => n + r.hits, 0)).toBe(16);
    expect(conds.map((r) => r.i)).toEqual([
      643, 684, 688, 692, 696, 700, 704, 708, 712, 716, 720, 724, 728, 756, 760,
    ]);
  });

  it('THE FOURTH ai SITE is read from the source — spawn x, facing and the bow', () => {
    const at = mgr[OG_AI_DUEL_PLACEMENT.line - 1] ?? '';
    expect(at).toContain('isDuelMode() && xml.ai == 0');
    const block = mgr.slice(OG_AI_DUEL_PLACEMENT.line, OG_AI_DUEL_PLACEMENT.line + 14).join('\n');
    expect(block).toContain(`setPosition(${String(OG_AI_DUEL_PLACEMENT.rightPos.x)},y)`);
    expect(block).toContain(`setPosition(${String(OG_AI_DUEL_PLACEMENT.leftPos.x)},y)`);
    expect(block).toContain(`actor.mcs.${OG_AI_DUEL_PLACEMENT.rightPos.facing}()`);
    expect(block).toContain(`startAnim(MCSActor.${OG_AI_DUEL_PLACEMENT.anim})`);
    // The two x's are the OPPOSITE ends of the 800px stage — right stands at 650.
    expect(OG_AI_DUEL_PLACEMENT.rightPos.x).toBeGreaterThan(OG_AI_DUEL_PLACEMENT.leftPos.x);
  });

  it('every committed ai VALUE appears in the source condition it claims', () => {
    for (const d of [OG_AI_CREATE_ROOM_NPC, OG_AI_CREATE_ROOM_NPC_PROCGEN]) {
      for (const c of d.cases) {
        // The condition sits a couple of lines above its constructor.
        const window = mgr.slice(c.line - 4, c.line).join('\n');
        expect(window, `${d.fn} ai ${String(c.ai)}`).toContain(`xml.ai == ${String(c.ai)}`);
      }
    }
  });

  it('the four in-code ai overrides really sit on those XMLNpc.as lines', () => {
    for (const o of OG_AI_CODE_OVERRIDES) {
      expect(xmlnpc[o.line - 1]?.trim(), `XMLNpc.as:${String(o.line)}`).toBe(
        `this.ai = ${o.assigns};`,
      );
    }
    // Exactly SIX `this.ai =` statements exist; the two not recorded are the
    // constructor's read-or-default, and a seventh appearing must turn this red.
    const all = xmlnpc
      .map((l, i) => (/^\s*this\.ai = .+;\s*$/.test(l) ? i + 1 : -1))
      .filter((i) => i > 0);
    expect(all).toEqual([137, 141, 315, 479, 523, 586]);
    expect(xmlnpc[136]?.trim()).toBe('this.ai = xml.ai;');
    expect(xmlnpc[140]?.trim()).toBe('this.ai = 1;');
  });

  it('isAnimal() is read from the source, not retyped', () => {
    const line = xmlnpc.find((l) => l.includes('return this.ai == '));
    expect(line).toBeDefined();
    expect([...(line ?? '').matchAll(/this\.ai == (\d+)/g)].map((m) => Number(m[1]))).toEqual([
      ...OG_AI_ANIMAL_VALUES,
    ]);
  });

  it('THE COINCIDENCE TRAP: the two 34s are DISJOINT SETS, not one fact twice', () => {
    const classes = readdirSync(SCRIPTS).filter((f) => f.endsWith('.as'));
    const enemies = classes.filter((f) => f.startsWith('Enemy'));
    const friendlies = classes.filter((f) => f.startsWith('Friendly'));
    const rooms = classes.filter((f) => f.startsWith('Room') && f !== 'RoomGenNode.as');
    expect(enemies.length).toBe(34);
    expect(friendlies.length).toBe(3);
    expect(rooms.length).toBe(3);
    // The OTHER 34: distinct <ai> values in the data.
    const aiValues = new Set(OG_NPCS.map((n) => n.ai).filter((v): v is number => v !== undefined));
    expect(aiValues.size).toBe(34);
    // Same number, different kinds of thing — and they cannot even be aligned:
    // 4 enemy classes are never named by any dispatch, and 4 dispatched values are
    // never used by the data. Neither 34 verifies the other.
    const named = new Set(
      ALL.flatMap((d) => [
        ...d.cases.map((c) => `${c.actor}.as`),
        ...(d.fallback.kind === 'actor' ? [`${d.fallback.actor}.as`] : []),
      ]),
    );
    expect(enemies.filter((f) => !named.has(f)).sort()).toEqual([
      'EnemyClone.as',
      'Enemy_VegePatch.as',
    ]);
  });
});
